import {chromium} from 'playwright';
import {mkdirSync} from 'node:fs';

const base = process.argv[2] || 'http://localhost:4173';
const out = '/tmp/shots';
mkdirSync(out, {recursive: true});

const browser = await chromium.launch();
const log = [];
async function run(theme) {
  const page = await browser.newPage({viewport: {width: 1200, height: 640}, deviceScaleFactor: 1});
  const chunks = [];
  page.on('request', (r) => { if (r.url().endsWith('.js')) chunks.push(r.url().split('/').pop()); });
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') log.push(`[${theme}] console.${m.type()}: ${m.text()}`); });
  page.on('pageerror', (e) => log.push(`[${theme}] pageerror: ${e.message}`));

  await page.goto(`${base}/?theme=${theme}`);
  await page.waitForSelector('.chart-widget svg path', {timeout: 20000});
  await page.waitForTimeout(600);
  await page.screenshot({path: `${out}/${theme}-sales.png`});
  const afterSales = [...chunks];

  // hover crosshair + tooltip on sales
  const box = await page.locator('.chart-widget__chart').boundingBox();
  await page.mouse.move(box.x + box.width * 0.55, box.y + box.height * 0.45);
