const a=`            tooltip: {show: true, tracking: 'sticky', sum: false, highlight: true, maxLines: 10},`;
if(!m.includes(a)) throw new Error('anchor');
m=m.replace(a,`            tooltip: {
                show: true,
                tracking: 'sticky',
                sum: false,
                highlight: true,
                maxLines: 10,
                // Порядок строк как в исходных данных (ChartKit по умолчанию разворачивает его).
                sort: (a, b) => a.rowIdx - b.rowIdx,
            },`);
fs.writeFileSync('src/widget/engines/monitoring.ts',m);
